/*
 * OCR B GCSE Chemistry (J258) Twenty First Century Science — Exam Practice Question Bank
 * 40 written exam-style questions per topic, 1-mark recall to 6-mark extended response.
 * Each question has a markScheme (one (1) per mark); 6-mark questions use Level 3/2/1
 * descriptors followed by indicative content.
 * Supports diagram:true for questions requiring a sketch — the practice page renders a
 * drawing canvas alongside the textarea.
 * Questions marked [HT] assess Higher-tier-only (bold) learning outcomes.
 */

const CHEMISTRY_OCR_B_GCSE_PRACTICE = {

  /* ═══════════════════════════════════════ C1 — Air and Water */
  'C1': {
    name: 'Air and Water',
    questions: [
      { q: `Describe the arrangement and movement of particles in a solid, a liquid and a gas.`, marks: 3, markScheme: `• Solid: particles close together in a regular arrangement, vibrating about fixed positions (1)\n• Liquid: particles close together but randomly arranged, able to move past each other (1)\n• Gas: particles far apart, randomly arranged, moving quickly in all directions (1)` },
      { q: `State the difference between a physical change and a chemical change.`, marks: 2, markScheme: `• In a physical change (e.g. a change of state) no new substance is made and the change is easily reversed (1)\n• In a chemical change a new substance (product) is made, because atoms are rearranged into new combinations (1)` },
      { q: `A student says: "Copper particles are orange and shiny because a lump of copper is orange and shiny." Explain why the student is wrong.`, marks: 2, markScheme: `• Individual particles (atoms) do not have the bulk properties of the substance (1)\n• Properties such as colour and shininess arise from the way very large numbers of particles are arranged and interact (1)` },
      { q: `Water is heated from −20 °C to 120 °C at a steady rate. Sketch the heating curve you would expect (temperature against time) and label the melting and boiling points.`, marks: 3, diagram: true, markScheme: `• Rising line from −20 °C, then a horizontal section at 0 °C labelled melting (1)\n• Rising line, then a horizontal section at 100 °C labelled boiling (1)\n• Final rising section above 100 °C, with the boiling plateau longer than the melting plateau (1)` },
      { q: `Explain why the temperature of stearic acid stays constant while it is freezing, even though it is losing energy to the surroundings.`, marks: 3, markScheme: `• As the liquid freezes, forces of attraction form between the particles (1)\n• Forming these attractions transfers energy to the surroundings (1)\n• This energy balances the energy lost, so the average kinetic energy of the particles (temperature) does not change until all of it has solidified (1)` },
      { q: `Describe how you would plot a cooling curve for stearic acid in the laboratory.`, marks: 4, markScheme: `• Melt stearic acid in a boiling tube in a hot water bath (1)\n• Put a thermometer (or temperature probe) in the liquid and remove the tube from the water bath (1)\n• Record the temperature at regular intervals, e.g. every 30 seconds, until it is well below the freezing point (1)\n• Plot temperature (y-axis) against time (x-axis); the flat section shows the freezing point (1)` },
      { q: `Explain why sodium chloride melts at 801 °C but water melts at 0 °C.`, marks: 3, markScheme: `• To melt, energy must be transferred to overcome the forces between particles (1)\n• In sodium chloride there are strong forces (electrostatic attraction) between ions (1)\n• Between water molecules the forces are much weaker, so much less energy is needed and the melting point is lower (1)` },
      { q: `The melting point of ethanol is −114 °C and its boiling point is 78 °C. Predict the state of ethanol at (a) −120 °C, (b) 25 °C and (c) 90 °C.`, marks: 3, markScheme: `• (a) Solid (below the melting point) (1)\n• (b) Liquid (between melting and boiling points) (1)\n• (c) Gas (above the boiling point) (1)` },
      { q: `In the simple particle model, particles are drawn as small, solid, inelastic spheres. Give three limitations of this model when it is used to explain changes of state. [HT]`, marks: 3, markScheme: `• It does not show the true scale: real particles are far smaller and the spaces between gas particles are much larger than drawn (1)\n• Real particles are not hard inelastic spheres; they are atoms/molecules made of smaller particles and have shapes (1)\n• It does not show the forces / different interactions between particles, so it cannot explain why substances change state at different temperatures (1)` },
      { q: `Describe how scientists think the Earth's early atmosphere and oceans formed.`, marks: 4, markScheme: `• Intense volcanic activity released gases from inside the Earth (1)\n• The early atmosphere was mainly carbon dioxide, with water vapour (and small amounts of other gases such as nitrogen, methane, ammonia) (1)\n• There was little or no oxygen (1)\n• As the Earth cooled, water vapour condensed to form the oceans (1)` },
      { q: `Describe how the amount of oxygen in the atmosphere increased over time.`, marks: 3, markScheme: `• Simple organisms evolved that could photosynthesise (algae / plants) (1)\n• Photosynthesis takes in carbon dioxide and releases oxygen (1)\n• Over billions of years oxygen built up, allowing animals to evolve (1)` },
      { q: `Scientists have found 3.5-billion-year-old rocks containing fossilised bacteria, and iron-rich rock layers about 2.4 billion years old that contain iron oxide. Explain how each piece of evidence supports the idea that photosynthesis changed the atmosphere. Identify which part is data and which part is an explanation.`, marks: 4, markScheme: `• Fossil bacteria show that early life existed, which could have included photosynthesising organisms (1)\n• Iron oxide layers show that free oxygen was present to oxidise the iron at that time (1)\n• Data: the ages and the observations of the rocks/fossils (1)\n• Explanation: the idea that photosynthesis produced the oxygen that caused these changes (1)` },
      { q: `Write a word equation for the complete combustion of methane.`, marks: 2, markScheme: `• methane + oxygen → (1)\n• carbon dioxide + water (1)` },
      { q: `Balance the equation for the complete combustion of methane: CH₄ + O₂ → CO₂ + H₂O`, marks: 2, markScheme: `• 2O₂ on the left-hand side (1)\n• 2H₂O on the right-hand side: CH₄ + 2O₂ → CO₂ + 2H₂O (1)` },
      { q: `Explain why burning a fuel in a limited supply of air produces carbon monoxide and particulates.`, marks: 3, markScheme: `• There is not enough oxygen for complete combustion / incomplete combustion occurs (1)\n• Some carbon is only partly oxidised to carbon monoxide (CO) (1)\n• Some carbon is not oxidised at all and is released as solid particles (soot / particulates) (1)` },
      { q: `Describe how sulfur dioxide and oxides of nitrogen are formed when fuels are burned.`, marks: 3, markScheme: `• Sulfur dioxide forms when sulfur impurities in the fuel react with oxygen (1)\n• Nitrogen and oxygen from the air react at the high temperatures in engines to form nitrogen monoxide (NO) (1)\n• NO is further oxidised in the air to nitrogen dioxide (NO₂) (1)` },
      { q: `Explain the problems caused by sulfur dioxide, nitrogen oxides and particulates in the air.`, marks: 4, markScheme: `• Sulfur dioxide and nitrogen oxides dissolve in rain water to form acid rain (1)\n• Acid rain damages buildings, plants/trees and aquatic life (1)\n• Nitrogen oxides contribute to photochemical smog and cause breathing problems (1)\n• Particulates cause lung/respiratory problems and global dimming (1)` },
      { q: `Describe three approaches used to reduce the emission of pollutants from burning fuels, stating which pollutant each reduces.`, marks: 3, markScheme: `• Catalytic converters in cars convert carbon monoxide and nitrogen oxides into carbon dioxide and nitrogen (1)\n• Low sulfur petrol/diesel: sulfur is removed from the fuel before burning, reducing sulfur dioxide (1)\n• Gas scrubbers in power stations remove sulfur dioxide from waste gases (e.g. by reacting with an alkali such as calcium oxide) (1)` },
      { q: `Explain why combustion is described as an oxidation reaction.`, marks: 2, markScheme: `• Oxidation is the gain of oxygen (1)\n• In combustion the fuel (carbon and hydrogen atoms) combines with oxygen (1)` },
      { q: `Write the formulae of: (a) oxygen gas, (b) carbon dioxide, (c) sulfur dioxide, (d) nitrogen dioxide.`, marks: 4, markScheme: `• O₂ (1)\n• CO₂ (1)\n• SO₂ (1)\n• NO₂ (1)` },
      { q: `Describe the tests for oxygen, hydrogen and carbon dioxide, giving the positive result for each.`, marks: 6, markScheme: `Level 3 (5–6 marks): all three tests described with the correct positive result for each.\nLevel 2 (3–4 marks): two tests described with results, or three tests with some results missing.\nLevel 1 (1–2 marks): one test or result given.\nIndicative content:\n• Oxygen: insert a glowing splint (1)\n• The splint relights (1)\n• Hydrogen: hold a lighted splint at the mouth of the tube (1)\n• Burns with a squeaky pop (1)\n• Carbon dioxide: bubble the gas through limewater (1)\n• Limewater turns milky/cloudy (1)` },
      { q: `State what is meant by an exothermic and an endothermic reaction in terms of the temperature of the surroundings.`, marks: 2, markScheme: `• Exothermic: transfers energy to the surroundings so the temperature of the surroundings rises (1)\n• Endothermic: takes in energy from the surroundings so the temperature of the surroundings falls (1)` },
      { q: `Draw a labelled reaction profile for an exothermic reaction. Label the reactants, products, activation energy and the energy change.`, marks: 4, diagram: true, markScheme: `• Products drawn lower in energy than reactants (1)\n• Curve rising to a peak between reactants and products (1)\n• Activation energy shown as an arrow from reactants up to the peak (1)\n• Energy change (energy given out) shown as the difference between reactants and products (1)` },
      { q: `Draw a labelled reaction profile for an endothermic reaction, showing the activation energy.`, marks: 3, diagram: true, markScheme: `• Products drawn higher in energy than reactants (1)\n• Curve with a peak above the products (1)\n• Activation energy labelled from reactants to the peak (1)` },
      { q: `Explain what is meant by activation energy and why a fuel needs a flame or spark before it will burn.`, marks: 2, markScheme: `• Activation energy is the minimum energy needed for a reaction to occur / to start breaking bonds (1)\n• The flame or spark supplies this energy to start breaking bonds in the reactants (1)` },
      { q: `Explain, in terms of bond breaking and bond making, why some reactions are exothermic.`, marks: 3, markScheme: `• Breaking bonds requires (takes in) energy (1)\n• Making bonds releases (gives out) energy (1)\n• In an exothermic reaction more energy is released making new bonds than is taken in breaking bonds (1)` },
      { q: `Hydrogen burns in chlorine: H–H + Cl–Cl → 2 H–Cl. Bond energies: H–H = 436 kJ/mol, Cl–Cl = 243 kJ/mol, H–Cl = 432 kJ/mol. Calculate the energy change for the reaction and state whether it is exothermic or endothermic. [HT]`, marks: 4, markScheme: `• Energy to break bonds = 436 + 243 = 679 kJ/mol (1)\n• Energy released making bonds = 2 × 432 = 864 kJ/mol (1)\n• Energy change = 679 − 864 = −185 kJ/mol (1)\n• Exothermic, because more energy is released than taken in (1)` },
      { q: `Describe how you would investigate whether the reaction between citric acid solution and sodium hydrogencarbonate is exothermic or endothermic.`, marks: 4, markScheme: `• Measure a fixed volume of citric acid solution into a polystyrene cup (insulated container) (1)\n• Measure its starting temperature with a thermometer (1)\n• Add the sodium hydrogencarbonate, stir and record the lowest/highest temperature reached (1)\n• If the temperature falls it is endothermic; if it rises it is exothermic (1)` },
      { q: `State when a chemical cell stops producing a potential difference.`, marks: 1, markScheme: `• When one of the reactants is used up (1)` },
      { q: `Evaluate the use of hydrogen–oxygen fuel cells instead of petrol engines to power cars.`, marks: 6, markScheme: `Level 3 (5–6 marks): advantages and disadvantages are explained and a justified conclusion is reached.\nLevel 2 (3–4 marks): some advantages and disadvantages are described.\nLevel 1 (1–2 marks): a simple advantage or disadvantage is given.\nIndicative content:\n• The only product is water, so no CO₂, CO, NOₓ or particulates are released at the car / city air quality improves (1)\n• Fuel cells convert chemical energy directly to electrical energy and are more efficient than combustion engines (1)\n• Hydrogen is usually made by electrolysis, which may use electricity from fossil fuels, so pollution happens elsewhere (1)\n• Hydrogen is a gas that is difficult to store; it needs high-pressure tanks and is flammable/explosive (1)\n• There are few hydrogen filling stations and fuel cells are expensive (1)\n• Conclusion: beneficial in cities if hydrogen is made using renewable electricity, but storage and cost currently limit their use (1)` },
      { q: `Describe the greenhouse effect in terms of the interaction of radiation with matter.`, marks: 4, markScheme: `• Radiation from the Sun (mainly visible/short wavelength) passes through the atmosphere and is absorbed by the Earth's surface, warming it (1)\n• The warm Earth emits infrared radiation (1)\n• Greenhouse gases such as carbon dioxide, methane and water vapour absorb some of this infrared (1)\n• They re-emit it in all directions, including back towards the Earth, keeping it warmer than it would otherwise be (1)` },
      { q: `Between 1960 and 2020 the carbon dioxide concentration measured at Mauna Loa rose from 317 ppm to 414 ppm, while world fossil fuel use roughly trebled. Explain why this correlation alone does not prove that burning fossil fuels caused the increase, and give one reason why most scientists accept that it did.`, marks: 3, markScheme: `• A correlation shows the two variables change together but does not by itself show that one causes the other (1)\n• Another factor (e.g. deforestation, volcanic activity, natural cycles) could contribute (1)\n• A plausible mechanism exists: burning fossil fuels releases CO₂, and CO₂ absorbs infrared, so scientists accept the causal link (1)` },
      { q: `Describe the potential effects of increasing levels of carbon dioxide and methane on the Earth's climate.`, marks: 4, markScheme: `• Rising global temperatures change where crops can be grown (1)\n• More frequent and severe extreme weather events (storms, droughts, heatwaves) (1)\n• Melting of polar ice caps and glaciers (1)\n• Rising sea levels causing flooding of low-lying land (1)` },
      { q: `Discuss ways of reducing the effects of increased carbon dioxide emissions, including problems of scale and risk.`, marks: 6, markScheme: `Level 3 (5–6 marks): several methods described, with clear discussion of scale, risk and environmental implications.\nLevel 2 (3–4 marks): some methods described with some discussion of problems.\nLevel 1 (1–2 marks): one or two methods named.\nIndicative content:\n• Reduce fossil fuel use by switching to renewable energy and improving energy efficiency (1)\n• Carbon capture and storage: CO₂ is captured at power stations and stored underground (1)\n• Reforestation: trees remove CO₂ by photosynthesis (1)\n• Measures need public regulation / international agreement on emission targets to work (1)\n• The scale is very large: billions of tonnes of CO₂ are emitted each year, so each measure alone has a small effect (1)\n• New measures may have unforeseen environmental impacts (e.g. stored CO₂ leaking), making risk–benefit judgements difficult (1)` },
      { q: `Describe how ground water from an aquifer is treated to make it potable (safe to drink).`, marks: 3, markScheme: `• Filtration (e.g. through sand/gravel beds) removes insoluble solids (1)\n• Membrane filtration can remove very small particles and some microorganisms (1)\n• Chlorination kills remaining microorganisms (1)` },
      { q: `Explain why producing potable water from waste water (sewage) involves more treatment stages than producing it from ground water.`, marks: 4, markScheme: `• Waste water contains much more organic matter, solids and harmful microorganisms (1)\n• Solids are removed by screening/filtration and sedimentation (1)\n• Aeration supplies oxygen so that bacteria can break down the organic matter (1)\n• The water must then be filtered (e.g. membrane filtration) and chlorinated to kill remaining microorganisms (1)` },
      { q: `Explain why distillation can make potable water from sea water, and why it is not widely used in countries with plenty of fresh water.`, marks: 4, markScheme: `• Sea water is heated so that the water boils and the vapour is condensed (1)\n• The dissolved salts have very high boiling points and are left behind (1)\n• Boiling large volumes of water needs a large amount of energy, so it is expensive (1)\n• It is only economic where fresh water is scarce and energy is cheap/available (1)` },
      { q: `Describe the test for chlorine gas and give the positive result.`, marks: 2, markScheme: `• Hold damp blue litmus paper in the gas (1)\n• The paper turns red and then is bleached white (1)` },
      { q: `Chlorine is added to drinking water at about 1 mg per litre. Chlorine is toxic in large amounts. Explain why the benefits of chlorinating water are judged to outweigh the risks.`, marks: 3, markScheme: `• Chlorine kills microorganisms that cause waterborne diseases such as cholera and typhoid (1)\n• The concentration used is very low, so the risk of toxic effects is very small (1)\n• Many more lives are saved by preventing disease than are put at risk, which is why chlorination is regulated rather than banned (1)` },
      { q: `Carbon dioxide makes up about 0.04% of the atmosphere and nitrogen about 78%. Calculate how many times more nitrogen there is than carbon dioxide, and give the answer as an order of magnitude.`, marks: 2, markScheme: `• 78 ÷ 0.04 = 1950 (accept about 2000) times (1)\n• Order of magnitude 10³ (1)` },
    ],
  },


  /* ═══════════════════════════════════════ C2 — Chemical Patterns */
  'C2': {
    name: 'Chemical Patterns',
    questions: [
      { q: `Describe Dalton's model of the atom.`, marks: 2, markScheme: `• Atoms are tiny solid spheres that cannot be divided / created / destroyed (1)\n• Atoms of the same element are identical; atoms of different elements are different (1)` },
      { q: `Describe Thomson's 'plum pudding' model of the atom and the discovery that led to it.`, marks: 3, markScheme: `• Thomson discovered the electron (1)\n• So atoms must contain smaller, negatively charged particles and are not indivisible (1)\n• Model: a sphere of positive charge with negative electrons embedded in it (1)` },
      { q: `In Rutherford's gold foil experiment, alpha particles were fired at thin gold foil. Most passed straight through, a few were deflected and a very small number bounced back. Explain what each observation showed about the atom.`, marks: 3, markScheme: `• Most passed through: most of the atom is empty space (1)\n• Some deflected: the centre of the atom is positively charged and repels the positive alpha particles (1)\n• Very few bounced back: the positive charge and most of the mass are concentrated in a tiny nucleus (1)` },
      { q: `Describe how and why the model of the atom changed from Dalton to Bohr.`, marks: 6, markScheme: `Level 3 (5–6 marks): a detailed, logically ordered account of at least three models with the evidence that caused each change.\nLevel 2 (3–4 marks): describes at least two models with some linked evidence.\nLevel 1 (1–2 marks): simple statements about one or two models.\nIndicative content:\n• Dalton: atoms are solid, indivisible spheres; each element has its own type of atom (1)\n• Thomson discovered the electron, so atoms contain smaller particles (1)\n• Plum pudding model: positive sphere with electrons embedded (1)\n• Rutherford's alpha-scattering results could not be explained by the plum pudding model (1)\n• Nuclear model: tiny, dense, positive nucleus surrounded by mostly empty space containing electrons (1)\n• Bohr: electrons in fixed shells, which explained further experimental evidence; models were rejected or modified as new evidence appeared (1)` },
      { q: `State the relative charge and the approximate relative mass of a proton, a neutron and an electron.`, marks: 3, markScheme: `• Proton: charge +1, mass 1 (1)\n• Neutron: charge 0, mass 1 (1)\n• Electron: charge −1, mass very small (about 1/1840 / negligible) (1)` },
      { q: `Describe the structure of an atom in terms of where its charge and mass are found.`, marks: 3, markScheme: `• A positively charged nucleus at the centre, containing protons and neutrons (1)\n• Surrounded by negatively charged electrons in shells (1)\n• The nucleus is very small compared with the atom but contains almost all of the mass (1)` },
      { q: `State the typical diameter of an atom and the approximate size of its nucleus compared with the atom.`, marks: 2, markScheme: `• About 1 × 10⁻¹⁰ m (0.1 nm) (1)\n• The nucleus is about 1/100 000 of the diameter of the atom (about 10⁻¹⁵ m) (1)` },
      { q: `An atom has a diameter of 1 × 10⁻¹⁰ m. A grain of sand is 1 × 10⁻⁴ m across. Calculate roughly how many atoms would fit side by side across the grain of sand.`, marks: 2, markScheme: `• 1 × 10⁻⁴ ÷ 1 × 10⁻¹⁰ (1)\n• = 1 × 10⁶ (one million) atoms (1)` },
      { q: `An atom of potassium has atomic number 19 and mass number 39. Calculate the numbers of protons, neutrons and electrons in the atom.`, marks: 3, markScheme: `• Protons = 19 (1)\n• Neutrons = 39 − 19 = 20 (1)\n• Electrons = 19 (1)` },
      { q: `Chlorine has two isotopes, chlorine-35 and chlorine-37. Chlorine's atomic number is 17. Explain what is meant by isotopes, using these two atoms as an example.`, marks: 3, markScheme: `• Isotopes are atoms of the same element with the same number of protons but different numbers of neutrons (1)\n• Both have 17 protons (and 17 electrons) (1)\n• Chlorine-35 has 18 neutrons; chlorine-37 has 20 neutrons (1)` },
      { q: `Write the electron arrangement of (a) sodium (atomic number 11) and (b) chlorine (atomic number 17).`, marks: 2, markScheme: `• Sodium: 2.8.1 (1)\n• Chlorine: 2.8.7 (1)` },
      { q: `Draw a diagram to show the electron arrangement in an atom of magnesium (atomic number 12).`, marks: 2, diagram: true, markScheme: `• Three shells drawn around a central nucleus (1)\n• Correct numbers of electrons: 2, 8, 2 (1)` },
      { q: `An element has the electron arrangement 2.8.6. Explain how this tells you its group and period in the Periodic Table.`, marks: 3, markScheme: `• It has 6 electrons in its outer shell, so it is in Group 6 (1)\n• It has 3 occupied shells, so it is in Period 3 (1)\n• It is sulfur (atomic number 16, total 16 electrons) (1)` },
      { q: `Describe how Mendeleev arranged the elements in his Periodic Table.`, marks: 3, markScheme: `• In order of increasing relative atomic mass (1)\n• Elements with similar properties placed in the same group/column (1)\n• He left gaps for undiscovered elements and swapped the order of some elements (e.g. tellurium and iodine) so they fitted the pattern of properties (1)` },
      { q: `Explain how the discovery of new elements and of atomic number supported Mendeleev's decisions.`, marks: 4, markScheme: `• Mendeleev predicted the properties of elements to fill his gaps (1)\n• Elements such as gallium and germanium were later discovered with properties that matched his predictions (1)\n• Later, elements were ordered by atomic number (number of protons) (1)\n• Ordering by atomic number gave the same order as his reversals, explaining why he was right to swap them (1)` },
      { q: `Compare the physical properties of metals and non-metals.`, marks: 4, markScheme: `• Metals are shiny; non-metals are dull (1)\n• Metals generally have high melting and boiling points and are solids at room temperature; many non-metals have low melting/boiling points and are gases (1)\n• Metals conduct electricity and heat; non-metals (except graphite) do not (1)\n• Metals usually have high density; non-metals low density (1)` },
      { q: `Describe one chemical difference between metals and non-metals in terms of the oxides they form.`, marks: 2, markScheme: `• Metal oxides are basic / form alkaline solutions (1)\n• Non-metal oxides are acidic / form acidic solutions (1)` },
      { q: `Describe what you would see when a small piece of sodium is added to a large trough of water.`, marks: 3, markScheme: `• Sodium floats and moves around on the surface (1)\n• Fizzes / bubbles of gas are given off (1)\n• Melts into a ball and gets smaller until it disappears (1)` },
      { q: `Write a word equation and a balanced symbol equation, with state symbols, for the reaction of lithium with water.`, marks: 3, markScheme: `• lithium + water → lithium hydroxide + hydrogen (1)\n• 2Li + 2H₂O → 2LiOH + H₂ (1)\n• State symbols: Li(s), H₂O(l), LiOH(aq), H₂(g) (1)` },
      { q: `Explain why Group 1 metals are stored under oil and why their freshly cut surfaces quickly go dull.`, marks: 2, markScheme: `• They react quickly with oxygen and water vapour in moist air, so oil keeps air and water away (1)\n• The shiny surface reacts with oxygen to form a layer of oxide, which is dull (1)` },
      { q: `Explain why the reactivity of Group 1 metals increases down the group.`, marks: 3, markScheme: `• Group 1 atoms react by losing their one outer electron (1)\n• Down the group the outer electron is in a shell further from the nucleus / there are more shells (1)\n• So the outer electron is less strongly attracted and lost more easily (1)` },
      { q: `Give the state and colour at room temperature of chlorine, bromine and iodine.`, marks: 3, markScheme: `• Chlorine: pale green / yellow-green gas (1)\n• Bromine: red-brown (dark orange) liquid (1)\n• Iodine: grey-black solid (gives a purple vapour) (1)` },
      { q: `Chlorine water is added to potassium bromide solution. Describe what you would see, name the products and explain why the reaction happens.`, marks: 4, markScheme: `• The solution turns orange / yellow-orange (1)\n• Products: potassium chloride and bromine (1)\n• Chlorine is more reactive than bromine (1)\n• so chlorine displaces bromine from its compound (1)` },
      { q: `Write a balanced symbol equation for the reaction between chlorine and potassium iodide.`, marks: 2, markScheme: `• Correct formulae: Cl₂ + KI → KCl + I₂ (1)\n• Balanced: Cl₂ + 2KI → 2KCl + I₂ (1)` },
      { q: `Describe an experiment to show the reactivity pattern of chlorine, bromine and iodine using displacement reactions.`, marks: 6, markScheme: `Level 3 (5–6 marks): a clear method including all combinations, observations and a conclusion about the order of reactivity.\nLevel 2 (3–4 marks): a method with some combinations and some observations.\nLevel 1 (1–2 marks): a simple description of mixing halogens with halides.\nIndicative content:\n• Add a few drops of each halogen solution (chlorine water, bromine water, iodine solution) to separate solutions of potassium chloride, potassium bromide and potassium iodide in a spotting tile/test tubes (1)\n• Look for a colour change showing a new halogen has formed (1)\n• Chlorine turns potassium bromide orange and potassium iodide brown (1)\n• Bromine turns potassium iodide brown but does not react with potassium chloride (1)\n• Iodine does not react with either chloride or bromide (1)\n• Conclusion: reactivity order chlorine > bromine > iodine; reactivity decreases down Group 7 (1)` },
      { q: `Explain why the reactivity of the halogens decreases down Group 7.`, marks: 3, markScheme: `• Halogen atoms react by gaining one electron to complete their outer shell (1)\n• Down the group the outer shell is further from the nucleus (more shells) (1)\n• So the attraction for an extra electron is weaker and it is gained less easily (1)` },
      { q: `Astatine is below iodine in Group 7. Predict its state at room temperature and whether it would displace iodine from sodium iodide.`, marks: 2, markScheme: `• Solid (state trend: gas → liquid → solid down the group) (1)\n• No — astatine is less reactive than iodine, so it cannot displace it (1)` },
      { q: `Describe the properties of the Group 0 elements and explain why they are unreactive.`, marks: 4, markScheme: `• Colourless gases at room temperature (1)\n• Very low melting and boiling points; exist as single atoms (1)\n• Very unreactive / inert (1)\n• Because their atoms have full outer shells of electrons, so they do not need to lose, gain or share electrons (1)` },
      { q: `Explain how a sodium atom becomes a sodium ion, and give the charge on the ion.`, marks: 3, markScheme: `• The sodium atom (2.8.1) loses its one outer electron (1)\n• Giving a full outer shell (2.8) (1)\n• The ion has 11 protons and 10 electrons, so it has a charge of +1 (Na⁺) (1)` },
      { q: `Draw a dot and cross diagram to show the ions formed when sodium reacts with chlorine. Show the outer shell electrons only.`, marks: 3, diagram: true, markScheme: `• Na⁺ shown with no outer electrons (or a full shell of 8 crosses in the next shell) (1)\n• Cl⁻ shown with 8 outer electrons: 7 dots and 1 cross (1)\n• Charges shown on both ions, with brackets (1)` },
      { q: `Draw a dot and cross diagram to show the bonding in magnesium oxide. Show the outer shell electrons only.`, marks: 3, diagram: true, markScheme: `• Mg²⁺ with no outer-shell electrons shown (1)\n• O²⁻ with 8 outer electrons: 6 of one symbol and 2 of the other (1)\n• Correct charges, 2+ and 2−, with brackets (1)` },
      { q: `Explain ionic bonding in terms of electron transfer and electrostatic forces.`, marks: 3, markScheme: `• Metal atoms transfer (lose) electrons to non-metal atoms (1)\n• Forming positive metal ions and negative non-metal ions (1)\n• The oppositely charged ions are held together by strong electrostatic attraction in all directions (1)` },
      { q: `A calcium ion is written ⁴⁰₂₀Ca²⁺. Calculate the numbers of protons, neutrons and electrons in the ion.`, marks: 3, markScheme: `• Protons = 20 (1)\n• Neutrons = 40 − 20 = 20 (1)\n• Electrons = 20 − 2 = 18 (1)` },
      { q: `Explain why sodium chloride has a high melting point, dissolves in water and conducts electricity only when molten or dissolved.`, marks: 4, markScheme: `• Giant ionic lattice with strong electrostatic attraction between oppositely charged ions in all directions (1)\n• A large amount of energy is needed to overcome these attractions, so the melting point is high (1)\n• It dissolves because the charged ions are attracted to/interact with water molecules (1)\n• When molten or dissolved the ions are free to move and carry charge; in the solid they are held in fixed positions (1)` },
      { q: `Give two limitations of a ball and stick model of a sodium chloride lattice.`, marks: 2, markScheme: `• Shows the ions far apart with 'sticks' between them, but there are no sticks — the ions touch and are held by attraction in all directions (1)\n• Does not show the relative sizes of the ions correctly / the movement of electrons / the true scale (the lattice is much larger) (1)` },
      { q: `Use the charges on the ions to write the formulae of (a) potassium bromide, (b) lithium oxide and (c) calcium chloride. Ions: K⁺, Br⁻, Li⁺, O²⁻, Ca²⁺, Cl⁻.`, marks: 3, markScheme: `• KBr (1)\n• Li₂O (1)\n• CaCl₂ (1)` },
      { q: `Write a balanced symbol equation, with state symbols, for the reaction of potassium with bromine to form solid potassium bromide.`, marks: 3, markScheme: `• Correct formulae: K, Br₂, KBr (1)\n• Balanced: 2K + Br₂ → 2KBr (1)\n• State symbols: 2K(s) + Br₂(l) → 2KBr(s) (1)` },
      { q: `Give the meaning of each state symbol: (s), (l), (g) and (aq).`, marks: 2, markScheme: `• (s) solid, (l) liquid (1)\n• (g) gas, (aq) aqueous / dissolved in water (1)` },
      { q: `Give four general properties of transition metals that are different from those of Group 1 metals.`, marks: 4, markScheme: `• Higher melting points (1)\n• Higher densities (1)\n• Less reactive, e.g. silver and gold are very unreactive and do not corrode (1)\n• Form coloured ions with different charges and are used as catalysts, e.g. iron in the Haber process (1)` },
      { q: `Using copper and iron as examples, describe how transition metals form ions with different charges and coloured compounds.`, marks: 4, markScheme: `• Copper forms Cu⁺ and Cu²⁺ ions (1)\n• Copper(II) compounds such as copper(II) sulfate are blue (1)\n• Iron forms Fe²⁺ and Fe³⁺ ions (1)\n• Iron(II) compounds are pale green and iron(III) compounds are orange-brown (1)` },
    ],
  },


  /* ═══════════════════════════════════════ C3 — Chemicals of the Natural Environment */
  'C3': {
    name: 'Chemicals of the Natural Environment',
    questions: [
      { q: `Describe the structure and bonding in a metal.`, marks: 3, markScheme: `• Giant structure of positive metal ions arranged closely in a regular pattern (1)\n• Surrounded by a 'sea' of delocalised electrons that are free to move (1)\n• Held together by strong electrostatic attraction between the positive ions and the electrons (1)` },
      { q: `Explain, using the model of metallic bonding, why metals conduct electricity, are malleable and have high melting points.`, marks: 3, markScheme: `• Conduct: the delocalised electrons are free to move through the structure and carry charge (1)\n• Malleable: layers of ions can slide over each other but are still held together by the electrons (1)\n• High melting point: a lot of energy is needed to overcome the strong electrostatic attraction between the ions and the electrons (1)` },
      { q: `A student added small pieces of metals X, Y and Z to dilute hydrochloric acid. X fizzed rapidly, Y produced no bubbles and Z produced a few bubbles slowly. Put the metals in order of reactivity, most reactive first, and explain your answer.`, marks: 2, markScheme: `• X, Z, Y (1)\n• The faster the metal reacts / the more hydrogen bubbles produced, the more reactive the metal (1)` },
      { q: `Iron filings were added to copper sulfate solution. The blue solution became paler and a pink-brown solid formed. Explain these observations.`, marks: 3, markScheme: `• Iron is more reactive than copper (1)\n• Iron displaces copper from copper sulfate, forming iron sulfate (pale green/paler solution) (1)\n• The pink-brown solid is copper metal (1)` },
      { q: `A student heated mixtures of metal powders with metal oxides. Zinc + copper oxide: reacted, glowed. Iron + copper oxide: reacted. Zinc + iron oxide: reacted. Copper + iron oxide: no reaction. Copper + zinc oxide: no reaction. Iron + zinc oxide: no reaction. Deduce the order of reactivity of zinc, iron and copper and explain how the results show this.`, marks: 3, markScheme: `• Order: zinc > iron > copper (1)\n• Zinc removes oxygen from both iron oxide and copper oxide, so it is the most reactive (1)\n• Iron removes oxygen from copper oxide but not zinc oxide; copper reacts with neither, so it is least reactive (1)` },
      { q: `Explain how the reactivity of a metal is related to its tendency to form a positive ion.`, marks: 2, markScheme: `• Metals react by losing electrons to form positive ions (1)\n• The more easily a metal loses electrons / forms its positive ion, the more reactive it is (1)` },
      { q: `Write a balanced symbol equation for the reaction of magnesium with hydrochloric acid, including state symbols.`, marks: 3, markScheme: `• Correct formulae: Mg + HCl → MgCl₂ + H₂ (1)\n• Balanced: Mg + 2HCl → MgCl₂ + H₂ (1)\n• State symbols: Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g) (1)` },
      { q: `Zinc reacts with copper sulfate solution: Zn(s) + CuSO₄(aq) → ZnSO₄(aq) + Cu(s). Write the ionic equation for this reaction and explain which species is oxidised. [HT]`, marks: 3, markScheme: `• Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s) (sulfate ions are spectator ions) (1)\n• Zinc atoms lose electrons: Zn → Zn²⁺ + 2e⁻ (1)\n• So zinc is oxidised (and Cu²⁺ ions gain electrons and are reduced) (1)` },
      { q: `Write the ionic equation, including state symbols, for the displacement of silver by copper from silver nitrate solution. [HT]`, marks: 2, markScheme: `• Cu(s) + 2Ag⁺(aq) → Cu²⁺(aq) + 2Ag(s): correct species (1)\n• Correctly balanced (2Ag⁺, 2Ag) with state symbols (1)` },
      { q: `Explain why zinc can be extracted from zinc oxide by heating with carbon, but aluminium cannot be extracted from aluminium oxide this way.`, marks: 3, markScheme: `• Carbon is placed between aluminium and zinc in the reactivity series (1)\n• Carbon is more reactive than zinc, so it can remove oxygen from (reduce) zinc oxide (1)\n• Aluminium is more reactive than carbon, so carbon cannot reduce aluminium oxide; electrolysis must be used (1)` },
      { q: `Zinc oxide is reduced by carbon: ZnO + C → Zn + CO. Identify which substance is oxidised and which is reduced, in terms of oxygen.`, marks: 2, markScheme: `• Zinc oxide is reduced because it loses oxygen (1)\n• Carbon is oxidised because it gains oxygen (1)` },
      { q: `Describe the industrial extraction of zinc from its ore.`, marks: 4, markScheme: `• The zinc sulfide ore is roasted in air to form zinc oxide (1)\n• Zinc oxide is heated with carbon (coke) in a furnace (1)\n• Carbon reduces zinc oxide to zinc; carbon is oxidised to carbon monoxide/dioxide (1)\n• Zinc vapour is condensed and collected (1)` },
      { q: `Explain why electrolysis is used to extract some metals, and why it is expensive.`, marks: 3, markScheme: `• Metals more reactive than carbon (e.g. aluminium, sodium) cannot be extracted by reduction with carbon (1)\n• Electrolysis of the molten compound is used instead (1)\n• It needs a lot of electrical energy and energy to melt the ore, so it is expensive (1)` },
      { q: `Evaluate the use of bacteria (bioleaching) and plants (phytoextraction) to extract copper from low-grade ores and waste heaps. [HT]`, marks: 6, markScheme: `Level 3 (5–6 marks): both methods described, with advantages and disadvantages and a justified conclusion.\nLevel 2 (3–4 marks): at least one method described with some advantages or disadvantages.\nLevel 1 (1–2 marks): simple statements about one method.\nIndicative content:\n• Phytoextraction: plants grown on the ore/waste absorb metal ions; the plants are burned and the metal is extracted from the ash (1)\n• Bioleaching: bacteria convert metal compounds in the ore into soluble compounds, producing a solution of metal ions (leachate) (1)\n• Both can extract metals from low-grade ores and waste material that would be uneconomic to process by traditional methods (1)\n• They reduce the need to mine new ores, use less energy and reduce toxic metals in landfill (1)\n• But they are very slow and produce only small quantities of metal (1)\n• Conclusion: useful as resources run low and for cleaning up waste, but they cannot replace traditional extraction for large-scale demand (1)` },
      { q: `Define electrolysis and state what is meant by an electrolyte.`, marks: 2, markScheme: `• Electrolysis is the decomposition of a compound using an electric current (1)\n• An electrolyte is a molten or dissolved ionic compound in which the ions are free to move (1)` },
      { q: `Predict the products at the cathode and anode when molten (a) lead bromide and (b) zinc chloride are electrolysed.`, marks: 4, markScheme: `• (a) Cathode: lead (1)\n• (a) Anode: bromine (1)\n• (b) Cathode: zinc (1)\n• (b) Anode: chlorine (1)` },
      { q: `Describe what happens to the ions at each electrode during the electrolysis of molten sodium chloride.`, marks: 4, markScheme: `• Positive sodium ions are attracted to the negative electrode (cathode) (1)\n• Each Na⁺ ion gains an electron to form a sodium atom (1)\n• Negative chloride ions are attracted to the positive electrode (anode) (1)\n• Chloride ions lose electrons to form chlorine atoms, which pair up as Cl₂ molecules (1)` },
      { q: `Write half equations for the reactions at each electrode in the electrolysis of molten lead bromide, PbBr₂. [HT]`, marks: 2, markScheme: `• Cathode: Pb²⁺ + 2e⁻ → Pb (1)\n• Anode: 2Br⁻ → Br₂ + 2e⁻ (1)` },
      { q: `In the electrolysis of molten aluminium oxide the half equations are Al³⁺ + 3e⁻ → Al and 2O²⁻ → O₂ + 4e⁻. Explain which species is oxidised and which is reduced. [HT]`, marks: 2, markScheme: `• Aluminium ions are reduced because they gain electrons (1)\n• Oxide ions are oxidised because they lose electrons (1)` },
      { q: `Describe and explain how aluminium is extracted from aluminium oxide by electrolysis.`, marks: 6, markScheme: `Level 3 (5–6 marks): a detailed, logical account of the process, including reactions at both electrodes and why the anodes must be replaced.\nLevel 2 (3–4 marks): a description of the process with some electrode reactions.\nLevel 1 (1–2 marks): simple statements about electrolysis of aluminium oxide.\nIndicative content:\n• Aluminium is more reactive than carbon, so electrolysis is needed (1)\n• Aluminium oxide is heated to a very high temperature until molten so the ions can move (1)\n• Positive aluminium ions are attracted to the cathode, where they gain electrons to form aluminium atoms (molten aluminium collects at the bottom) (1)\n• Negative oxide ions are attracted to the anode, where they lose electrons to form oxygen (1)\n• The oxygen reacts with the hot carbon anodes to form carbon dioxide, so the anodes wear away and must be replaced (1)\n• The process uses a large amount of energy for the high temperature and the electric current, so it is expensive (1)` },
      { q: `Concentrated sodium chloride solution is electrolysed using inert electrodes. Name the product at each electrode and explain why sodium is not formed.`, marks: 4, markScheme: `• Cathode: hydrogen (1)\n• Anode: chlorine (1)\n• The solution contains H⁺ ions from the water as well as Na⁺ ions (1)\n• Sodium is more reactive than hydrogen, so hydrogen is discharged instead (1)` },
      { q: `Predict the products at each electrode when copper sulfate solution is electrolysed with inert electrodes. Explain your answers.`, marks: 4, markScheme: `• Cathode: copper (1)\n• Copper is less reactive than hydrogen, so copper ions are discharged rather than hydrogen ions (1)\n• Anode: oxygen (1)\n• There are no halide ions, so oxygen forms from hydroxide ions from the water (1)` },
      { q: `Describe how to electrolyse sodium chloride solution in the laboratory and test the products.`, marks: 6, markScheme: `Level 3 (5–6 marks): a clear, safe method that would collect and identify both gases.\nLevel 2 (3–4 marks): a workable method with some detail of collection or testing.\nLevel 1 (1–2 marks): basic statements about passing a current through the solution.\nIndicative content:\n• Pour sodium chloride solution into a beaker / electrolysis cell (1)\n• Place two inert (graphite/carbon) electrodes in the solution, not touching (1)\n• Connect the electrodes to a low-voltage d.c. power supply (1)\n• Collect gases by filling test tubes with the solution and inverting them over the electrodes (1)\n• Test the gas from the cathode with a lighted splint: squeaky pop shows hydrogen (1)\n• Test the gas from the anode with damp blue litmus paper: turns red then bleaches, showing chlorine; carry out in a well-ventilated room (1)` },
      { q: `State what crude oil is and give two reasons why it is important.`, marks: 3, markScheme: `• A mixture of hydrocarbons (compounds of hydrogen and carbon only) (1)\n• Source of fuels such as petrol, diesel and kerosene (1)\n• Feedstock for the petrochemical industry to make chemicals such as polymers (1)` },
      { q: `Explain why our current use of crude oil is not sustainable.`, marks: 2, markScheme: `• Crude oil is a finite / non-renewable resource that formed over millions of years (1)\n• It is being used up much faster than it forms, so it will run out (1)` },
      { q: `Describe and explain how crude oil is separated by fractional distillation.`, marks: 6, markScheme: `Level 3 (5–6 marks): a clear explanation linking temperature gradient, boiling points, molecule size and intermolecular forces.\nLevel 2 (3–4 marks): a description of the process with some explanation.\nLevel 1 (1–2 marks): simple statements about heating and separating.\nIndicative content:\n• Crude oil is heated until most of it evaporates and the vapour enters the column (1)\n• The column is hot at the bottom and cooler at the top (temperature gradient) (1)\n• Vapours rise and condense when they reach a level where the temperature is below their boiling point (1)\n• Fractions are collected at different heights; long-chain molecules (high boiling points) at the bottom, short chains (low boiling points) at the top (1)\n• Larger molecules have stronger intermolecular forces, so more energy is needed to separate them (1)\n• Each fraction is a mixture of hydrocarbons with similar boiling points (1)` },
      { q: `Draw a labelled diagram of a fractionating column, showing where crude oil vapour enters and where gases and bitumen leave.`, marks: 3, diagram: true, markScheme: `• Tall column with crude oil vapour entering near the bottom (from a heater/furnace) (1)\n• Temperature gradient labelled: hot at the bottom, cool at the top (1)\n• Refinery gases leaving at the top and bitumen/residue leaving at the bottom, with other fractions at intermediate heights (1)` },
      { q: `Give the general formula of the alkanes and use it to write the molecular formula of the alkane with 6 carbon atoms.`, marks: 2, markScheme: `• CₙH₂ₙ₊₂ (1)\n• C₆H₁₄ (1)` },
      { q: `Explain why butane (C₄H₁₀) has a higher boiling point than methane (CH₄).`, marks: 3, markScheme: `• Butane molecules are larger than methane molecules (1)\n• So the intermolecular forces between butane molecules are stronger (1)\n• More energy is needed to overcome them; no covalent bonds are broken when they boil (1)` },
      { q: `Deduce the empirical formula of (a) ethane, C₂H₆, and (b) butene, C₄H₈.`, marks: 2, markScheme: `• (a) CH₃ (1)\n• (b) CH₂ (1)` },
      { q: `Explain covalent bonding and draw a dot and cross diagram for a molecule of methane, CH₄.`, marks: 4, diagram: true, markScheme: `• A covalent bond is a shared pair of electrons between two non-metal atoms (1)\n• Carbon shares its 4 outer electrons with 4 hydrogen atoms (1)\n• Diagram: C in the centre with 4 shared pairs, each pair one dot and one cross (1)\n• No other electrons on the outer shell of carbon; each H has 2 electrons (1)` },
      { q: `Draw a dot and cross diagram for a water molecule, H₂O, showing outer shell electrons only.`, marks: 2, diagram: true, markScheme: `• Two shared pairs between O and each H (1)\n• Two non-bonding (lone) pairs on oxygen, giving 8 outer electrons in total around O (1)` },
      { q: `Give two limitations of using a ball and stick model to represent a methane molecule.`, marks: 2, markScheme: `• Bonds are not physical sticks; they are shared pairs of electrons (1)\n• Atoms are not to scale / the model does not show electrons or the relative sizes of atoms (1)` },
      { q: `Explain why decane is cracked, and write the equation for cracking decane (C₁₀H₂₂) into octane (C₈H₁₈) and one other product.`, marks: 4, markScheme: `• There is more demand for short-chain hydrocarbons such as petrol than supply from fractional distillation (1)\n• Cracking breaks long-chain alkanes into shorter, more useful alkanes (1)\n• and alkenes, which are used to make polymers (1)\n• C₁₀H₂₂ → C₈H₁₈ + C₂H₄ (1)` },
      { q: `Describe the test for an alkene and give the result.`, marks: 2, markScheme: `• Add bromine water and shake (1)\n• Orange bromine water is decolourised (turns colourless) with an alkene (alkanes leave it orange) (1)` },
      { q: `Draw the displayed formulae of ethene, ethanol and ethanoic acid, and circle the functional group in each.`, marks: 3, diagram: true, markScheme: `• Ethene: H₂C=CH₂ with all bonds shown; C=C circled (1)\n• Ethanol: CH₃CH₂OH with all bonds shown; –OH circled (1)\n• Ethanoic acid: CH₃COOH with all bonds shown; –COOH (C=O and O–H) circled (1)` },
      { q: `Predict the product when propene (C₃H₆) reacts with bromine, and write the equation.`, marks: 2, markScheme: `• 1,2-dibromopropane (accept dibromopropane), C₃H₆Br₂ (1)\n• C₃H₆ + Br₂ → C₃H₆Br₂ (1)` },
      { q: `Write balanced equations for (a) the complete combustion of ethanol and (b) the oxidation of ethanol to ethanoic acid using oxygen.`, marks: 4, markScheme: `• (a) C₂H₅OH + 3O₂ → (1)\n• 2CO₂ + 3H₂O (1)\n• (b) C₂H₅OH + O₂ → (1)\n• CH₃COOH + H₂O (1)` },
      { q: `The compounds CH₃OH, C₂H₅OH, C₃H₇OH and C₄H₉OH are the first four members of one homologous series. Name the series and the four compounds, and give two features shared by members of a homologous series.`, marks: 4, markScheme: `• Alcohols (functional group –OH) (1)\n• Methanol, ethanol, propanol, butanol (1)\n• Same general formula / each member differs from the next by CH₂ (1)\n• Same functional group so similar chemical reactions, with a trend in physical properties such as boiling point (1)` },
      { q: `Explain why ethene and propene both decolourise bromine water but ethane and propane do not.`, marks: 3, markScheme: `• Ethene and propene are alkenes and contain a C=C double bond (functional group) (1)\n• Bromine adds across the double bond in an addition reaction (1)\n• Alkanes have no functional group/only single bonds (saturated), so are unreactive; it is the functional group that determines the reactions (1)` },
    ],
  },


  /* ═══════════════════════════════════════ C4 — Material Choices */
  'C4': {
    name: 'Material Choices',
    questions: [
      { q: `Define the terms "brittle", "stiff" and "hard" as used to describe materials.`, marks: 3, markScheme: `• Brittle: breaks/shatters suddenly without bending or changing shape first (1)\n• Stiff: difficult to bend or stretch (does not deform much under a force) (1)\n• Hard: difficult to scratch or dent (1)` },
      { q: `Explain the difference between strength in tension and strength in compression, giving a material that is much stronger in compression than in tension.`, marks: 3, markScheme: `• Strength in tension: the pulling/stretching force a material can withstand before breaking (1)\n• Strength in compression: the squashing force a material can withstand before breaking (1)\n• Concrete (or clay ceramic / brick / glass) is strong in compression but weak in tension (1)` },
      { q: `Data for four materials — Material A: density 2.7 g/cm³, conducts electricity, melting point 660 °C, malleable. Material B: density 2.5 g/cm³, does not conduct, melting point about 1500 °C, brittle, transparent. Material C: density 0.95 g/cm³, does not conduct, softens at 130 °C, flexible. Material D: density 7.9 g/cm³, conducts electricity, melting point 1400 °C, strong in tension. Identify which material is most likely to be (a) a glass, (b) a polymer, (c) steel.`, marks: 3, markScheme: `• (a) B — brittle, transparent, high melting point, non-conductor (1)\n• (b) C — low density, softens at a low temperature, flexible (1)\n• (c) D — high density, conducts, strong in tension (1)` },
      { q: `Three materials have these properties. Material A: density 2.7 g/cm³, conducts electricity, malleable. Material C: density 0.95 g/cm³, insulator, softens at 130 °C, flexible. Material D: density 7.9 g/cm³, conducts electricity, strong in tension — choose the best material for (a) the outer case of a kettle plug and (b) an aircraft panel. Justify each choice.`, marks: 4, markScheme: `• (a) C (1)\n• Electrical insulator, so the user does not get a shock / can be moulded (1)\n• (b) A (1)\n• Low density (light) but still a metal that is strong/malleable (1)` },
      { q: `Compare the properties of clay ceramics and metals.`, marks: 4, markScheme: `• Ceramics are brittle; metals are malleable/ductile (1)\n• Ceramics are electrical insulators; metals conduct electricity (1)\n• Ceramics are hard and strong in compression; metals are strong in tension (1)\n• Both have high melting points (ceramics usually higher); ceramics cannot be reshaped once fired whereas metals can be reshaped (1)` },
      { q: `Explain what a composite material is and why reinforced concrete is used for bridges.`, marks: 4, markScheme: `• A composite is made of two or more materials combined, giving properties neither has alone (1)\n• Concrete is strong in compression but weak in tension (1)\n• Steel rods are strong in tension (1)\n• Together they are strong in both tension and compression, which a bridge needs (1)` },
      { q: `Explain why alloys are usually harder than the pure metal they are made from. You may draw a diagram to help your answer.`, marks: 3, diagram: true, markScheme: `• In a pure metal the atoms/ions are all the same size and arranged in regular layers that can slide over each other (1)\n• An alloy contains atoms of different sizes (1)\n• These distort the layers so they cannot slide easily, making the alloy harder (1)` },
      { q: `Steel is an alloy of iron. Give the main element added to iron to make steel and explain why stainless steel is used for cutlery.`, marks: 3, markScheme: `• Carbon (1)\n• Stainless steel also contains chromium (and nickel) (1)\n• It is hard and resistant to corrosion, so it does not rust when washed (1)` },
      { q: `Explain why low-carbon (mild) steel is used for car bodies but high-carbon steel is used for cutting tools.`, marks: 2, markScheme: `• Low-carbon steel is soft and easily shaped / malleable, so it can be pressed into car body panels (1)\n• High-carbon steel is very hard (but brittle), so it keeps a sharp edge (1)` },
      { q: `Describe how addition polymers are formed from monomers.`, marks: 3, markScheme: `• The monomers are small molecules containing a C=C double bond (alkenes) (1)\n• The double bond opens up (1)\n• Many monomers join together to form a long-chain polymer, with no other product (1)` },
      { q: `Draw the repeating unit of poly(ethene) and write an equation for its formation from n molecules of ethene.`, marks: 3, diagram: true, markScheme: `• Repeating unit: –CH₂–CH₂– with single C–C bond (1)\n• Brackets with extension bonds and n outside (1)\n• n C₂H₄ (H₂C=CH₂) → the bracketed repeating unit (1)` },
      { q: `Chloroethene has the structure H₂C=CHCl. Draw the repeating unit of the polymer it forms and name the polymer.`, marks: 3, diagram: true, markScheme: `• Two carbons joined by a single bond, with H, H on one and H, Cl on the other (1)\n• Extension bonds through brackets and n (1)\n• Poly(chloroethene) / PVC (1)` },
      { q: `The repeating unit of a polymer is –CH₂–CH(CH₃)–. Draw the monomer that was used to make it and name it.`, marks: 2, diagram: true, markScheme: `• H₂C=CH–CH₃ with a C=C double bond (1)\n• Propene (1)` },
      { q: `Describe how condensation polymerisation differs from addition polymerisation. [HT]`, marks: 4, markScheme: `• Condensation monomers have two functional groups each (e.g. –COOH and –OH or –NH₂) (1)\n• Usually two different monomers react together (1)\n• A small molecule, usually water, is formed each time a link forms (1)\n• Addition polymerisation uses one type of monomer with a C=C bond and the polymer is the only product (1)` },
      { q: `A polyester is made from a dicarboxylic acid HOOC–□–COOH and a diol HO–■–OH (□ and ■ represent the rest of each molecule). Draw the repeating unit of the polyester and name the small molecule formed. [HT]`, marks: 3, diagram: true, markScheme: `• Ester link –CO–O– shown joining the two monomer residues (1)\n• Repeating unit –[–CO–□–CO–O–■–O–]– with extension bonds/brackets and n (1)\n• Water (H₂O); 2n water molecules for n repeating units (1)` },
      { q: `Explain why a monomer must have at least two functional groups to form a condensation polymer, and name the type of polymer made when a dicarboxylic acid reacts with a diamine. [HT]`, marks: 3, markScheme: `• One functional group reacts with a monomer on one side and the other with a monomer on the other side (1)\n• So the chain can keep growing in both directions (with one group the chain would stop) (1)\n• A polyamide (e.g. nylon) (1)` },
      { q: `Name the monomers that make up DNA, proteins and starch.`, marks: 3, markScheme: `• DNA: four different nucleotides (1)\n• Proteins: amino acids (1)\n• Starch: sugars (glucose) (1)` },
      { q: `Explain why poly(ethene) has a much higher melting point than ethene, even though both contain the same types of covalent bonds.`, marks: 3, markScheme: `• Poly(ethene) molecules are very long chains (1)\n• So there are many more intermolecular forces between the molecules (stronger overall attraction) (1)\n• More energy is needed to overcome them, so the melting point is higher (1)` },
      { q: `Explain how cross-linking between polymer chains changes the properties of a polymer.`, marks: 3, markScheme: `• Cross-links are strong covalent bonds between chains (1)\n• They stop the chains sliding over each other (1)\n• So the polymer is stiffer, harder and stronger and does not soften/melt on heating (1)` },
      { q: `Explain why carbon can form a vast number of natural and synthetic compounds.`, marks: 3, markScheme: `• Carbon atoms form four covalent bonds (1)\n• Carbon atoms can bond to each other to form chains and rings of different lengths (1)\n• This produces families of similar compounds (homologous series) with a wide range of properties (1)` },
      { q: `Describe the structure and bonding in diamond and explain why diamond is very hard and has a very high melting point.`, marks: 4, markScheme: `• Giant covalent structure / each carbon atom covalently bonded to four other carbon atoms (1)\n• In a rigid three-dimensional (tetrahedral) lattice (1)\n• Very hard because the strong covalent bonds hold the atoms in fixed positions (1)\n• High melting point because a lot of energy is needed to break the many strong covalent bonds (1)` },
      { q: `Explain why graphite conducts electricity and can be used as a lubricant.`, marks: 4, markScheme: `• Each carbon atom is bonded to three others, forming flat layers of hexagons (1)\n• One electron from each atom is delocalised and free to move along the layers, so graphite conducts (1)\n• There are only weak forces between the layers (1)\n• So the layers slide over each other easily, making graphite slippery (1)` },
      { q: `Draw diagrams to show the arrangement of carbon atoms in diamond and in graphite.`, marks: 3, diagram: true, markScheme: `• Diamond: each atom joined to four others in a 3-D (tetrahedral) arrangement (1)\n• Graphite: hexagonal rings joined into flat layers (1)\n• Layers drawn stacked with gaps between them (no bonds between layers) (1)` },
      { q: `Compare the bonding and structure of sodium chloride, methane, diamond, poly(ethene) and copper, and use your comparison to explain their melting points.`, marks: 6, markScheme: `Level 3 (5–6 marks): bonding and structure of all five described accurately and clearly linked to melting points.\nLevel 2 (3–4 marks): bonding and structure of at least three described with some links to properties.\nLevel 1 (1–2 marks): simple statements about the bonding in one or two.\nIndicative content:\n• Sodium chloride: giant ionic lattice with strong electrostatic attraction between ions, so high melting point (1)\n• Methane: simple molecules with strong covalent bonds but weak intermolecular forces, so very low melting point (1)\n• Diamond: giant covalent structure with many strong covalent bonds to break, so very high melting point (1)\n• Poly(ethene): long covalently bonded chains with more intermolecular forces than small molecules, so melts/softens at a moderate temperature (1)\n• Copper: giant metallic lattice of positive ions in a sea of delocalised electrons, so high melting point (1)\n• Melting point depends on whether strong bonds (ionic, covalent, metallic) or only weak intermolecular forces must be overcome (1)` },
      { q: `State the size range of nanoparticles in nanometres and give the value of 1 nanometre in metres.`, marks: 2, markScheme: `• 1–100 nm (1)\n• 1 nm = 1 × 10⁻⁹ m (1)` },
      { q: `A nanoparticle has a diameter of 50 nm and an atom has a diameter of 0.1 nm. Calculate how many times larger the nanoparticle is than the atom, and write the nanoparticle diameter in metres in standard form.`, marks: 3, markScheme: `• 50 ÷ 0.1 (1)\n• = 500 times (1)\n• 5 × 10⁻⁸ m (1)` },
      { q: `Calculate the surface area to volume ratio of a cube with sides of 2 cm and of a cube with sides of 1 cm. State what happens to the ratio as the cube gets smaller.`, marks: 4, markScheme: `• 2 cm cube: surface area = 6 × 2² = 24 cm², volume = 2³ = 8 cm³ (1)\n• Ratio = 24 : 8 = 3 : 1 (1)\n• 1 cm cube: surface area 6 cm², volume 1 cm³, ratio 6 : 1 (1)\n• As the side length halves the ratio doubles / smaller particles have a larger surface area to volume ratio (1)` },
      { q: `A cube of a catalyst has sides of 1 × 10⁻⁸ m. Calculate its surface area and volume and the surface area to volume ratio.`, marks: 3, markScheme: `• Surface area = 6 × (1 × 10⁻⁸)² = 6 × 10⁻¹⁶ m² (1)\n• Volume = (1 × 10⁻⁸)³ = 1 × 10⁻²⁴ m³ (1)\n• Ratio = 6 × 10⁸ : 1 (per metre) (1)` },
      { q: `Explain why nanoparticles of platinum make better catalysts than larger particles of the same mass.`, marks: 3, markScheme: `• Nanoparticles have a very high surface area to volume ratio (1)\n• So more of the catalyst atoms are on the surface, where reactions take place (1)\n• So the same mass gives a faster reaction / less catalyst is needed, saving cost (1)` },
      { q: `Describe the structure of graphene and explain two of its properties.`, marks: 4, markScheme: `• A single layer of carbon atoms (one atom thick) (1)\n• Arranged in hexagons, each atom covalently bonded to three others (1)\n• Very strong because of the strong covalent bonds within the sheet (1)\n• Conducts electricity (and heat) because each atom has a delocalised electron that can move across the sheet (1)` },
      { q: `Describe the structures of fullerenes and explain how they can be used to deliver drugs and to strengthen sports equipment.`, marks: 4, markScheme: `• Fullerenes are molecules of carbon atoms arranged in hollow balls (e.g. C₆₀) or tubes (nanotubes), with rings of carbon atoms (1)\n• The hollow ball can carry a drug molecule inside it into the body (1)\n• Nanotubes are very strong and light (high tensile strength) (1)\n• They are incorporated into materials such as tennis racket frames to make them stronger without adding much mass (1)` },
      { q: `Discuss the possible benefits and risks of using nanoparticles in sun creams.`, marks: 6, markScheme: `Level 3 (5–6 marks): benefits and risks clearly explained with reference to size/surface area, data availability and a balanced judgement.\nLevel 2 (3–4 marks): some benefits and some risks described.\nLevel 1 (1–2 marks): one simple benefit or risk.\nIndicative content:\n• Benefit: nanoparticles (e.g. titanium dioxide, zinc oxide) give better protection against UV (1)\n• Benefit: they are transparent so they do not leave a white film on the skin (1)\n• Risk: their tiny size means they may pass through skin and enter cells/the bloodstream (1)\n• Risk: their large surface area may make them more reactive / toxic, and they may harm aquatic life when washed off (1)\n• There is more data about their uses than about their health effects because they are new and long-term effects take years to appear (1)\n• Judgement: balance the benefit (reduced skin cancer) against uncertain risks; more testing/regulation needed (1)` },
      { q: `Describe the conditions needed for iron to rust and name the product.`, marks: 3, markScheme: `• Oxygen (air) is needed (1)\n• Water is needed (1)\n• Product: hydrated iron(III) oxide (rust) (1)` },
      { q: `Explain how painting and galvanising each prevent iron from rusting, and why galvanising still protects iron if the coating is scratched.`, marks: 4, markScheme: `• Paint is a barrier that keeps oxygen and water away from the iron (1)\n• Galvanising coats the iron with zinc, which also acts as a barrier (1)\n• Zinc is more reactive than iron (1)\n• So zinc corrodes (is oxidised) in preference to iron even when scratched — sacrificial protection (1)` },
      { q: `In the reaction 4Fe + 3O₂ → 2Fe₂O₃, explain which substance is oxidised, using the idea of oxygen.`, marks: 2, markScheme: `• Iron is oxidised (1)\n• Because it gains oxygen (1)` },
      { q: `When iron rusts, iron atoms form Fe³⁺ ions. Write a half equation for this change and explain whether iron is oxidised or reduced. [HT]`, marks: 2, markScheme: `• Fe → Fe³⁺ + 3e⁻ (1)\n• Iron is oxidised because it loses electrons (1)` },
      { q: `Describe the stages considered in a life-cycle assessment (LCA) of a product and what is assessed at each stage.`, marks: 4, markScheme: `• Obtaining and processing the raw materials (1)\n• Manufacturing the product, including packaging and transport (1)\n• Using the product (1)\n• Disposal at end of life (landfill, incineration with electricity generation, recycling); at each stage the use of energy, water and resources, and pollution/environmental impact are assessed (1)` },
      { q: `An LCA compares two shopping bags. Paper bag: 1.7 MJ energy, 0.5 kg CO₂, biodegradable, used once. Poly(ethene) bag: 1.4 MJ energy, 0.3 kg CO₂, not biodegradable, can be reused about 5 times. Evaluate which bag has the lower environmental impact.`, marks: 4, markScheme: `• The poly(ethene) bag uses less energy (1.4 vs 1.7 MJ) and produces less CO₂ (0.3 vs 0.5 kg) per bag (1)\n• Being reused 5 times reduces its impact per use further (1)\n• The paper bag is biodegradable, so it causes less long-term litter/landfill problems (1)\n• Conclusion: the poly(ethene) bag has the lower impact if it is reused, but LCAs depend on data quality and on people following disposal advice (1)` },
      { q: `Describe how PET drinks bottles are reused and recycled, and explain why recycling PET is viable.`, marks: 6, markScheme: `Level 3 (5–6 marks): reuse and recycling processes described, with a clear explanation of the factors that make recycling viable.\nLevel 2 (3–4 marks): a description of recycling with some reasons for viability.\nLevel 1 (1–2 marks): simple statements about reuse or recycling.\nIndicative content:\n• Bottles can be washed and refilled (reused), which uses less energy than recycling (1)\n• For recycling, bottles are collected and sorted from other plastics (1)\n• They are washed to remove impurities and labels, then shredded into flakes (1)\n• The flakes are melted and made into new products such as fibres for clothing/fleece or new bottles (1)\n• Viable because large numbers of bottles are available and are easy to identify/collect and sort (1)\n• It conserves crude oil, reduces landfill and there is a demand for the recycled product (1)` },
      { q: `Evaluate the factors that affect whether it is worth recycling aluminium cans compared with making new aluminium from its ore.`, marks: 4, markScheme: `• Recycling aluminium uses much less energy than extracting it by electrolysis (1)\n• It conserves the finite supply of ore and reduces mining and landfill (1)\n• But cans must be collected, transported and sorted, which costs money and energy (1)\n• Recycling is viable because cans are plentiful, easy to separate (e.g. not magnetic) and the demand for aluminium is high (1)` },
    ],
  },


  /* ═══════════════════════════════════════ C5 — Chemical Analysis */
  'C5': {
    name: 'Chemical Analysis',
    questions: [
      { q: `Explain what is meant by a formulation and give two examples.`, marks: 3, markScheme: `• A mixture designed as a useful product (1)\n• Its components are mixed in carefully measured, definite proportions, each with a particular purpose (1)\n• Examples: paints, medicines/drugs, fertilisers, cleaning products, alloys, cosmetics (any two) (1)` },
      { q: `A carton of orange juice is labelled "100% pure". Explain how a chemist's meaning of "pure" differs from the everyday meaning.`, marks: 2, markScheme: `• Everyday: pure means nothing added / natural / unadulterated (1)\n• Chemist: a pure substance contains only one element or compound, whereas orange juice is a mixture of many substances (1)` },
      { q: `A sample of aspirin melts between 128 °C and 133 °C. Pure aspirin melts at 136 °C. Is the sample pure? Explain your answer.`, marks: 2, markScheme: `• Not pure (1)\n• It melts over a range of temperatures and below the melting point of pure aspirin; a pure substance has a sharp melting point (1)` },
      { q: `State what is meant by the stationary phase and the mobile phase in paper chromatography, and explain why substances separate.`, marks: 3, markScheme: `• Stationary phase: the paper (or the water held in it), which does not move (1)\n• Mobile phase: the solvent, which moves up the paper (1)\n• Substances separate because they distribute differently between the two phases; those more attracted to/more soluble in the mobile phase travel further (1)` },
      { q: `In a chromatogram the solvent front moved 8.0 cm from the start line and a spot moved 3.6 cm. Calculate the Rf value of the spot.`, marks: 2, markScheme: `• Rf = distance moved by spot ÷ distance moved by solvent = 3.6 ÷ 8.0 (1)\n• = 0.45 (1)` },
      { q: `A food dye gave three spots with Rf values 0.20, 0.45 and 0.78. Reference dyes gave: E102 Rf 0.45, E110 Rf 0.62, E133 Rf 0.78, E124 Rf 0.20. Identify the dyes present and explain how you know the food dye is a mixture.`, marks: 3, markScheme: `• E124, E102 and E133 (1)\n• E110 is not present (1)\n• It produced three spots, so it contains more than one substance (a pure substance gives only one spot) (1)` },
      { q: `Explain when a non-aqueous solvent and a locating agent are needed in chromatography.`, marks: 2, markScheme: `• A non-aqueous solvent (e.g. ethanol, propanone) is used when the substances are insoluble in water (1)\n• A locating agent (e.g. ninhydrin, iodine, UV light) is used to make spots of colourless substances visible (1)` },
      { q: `Describe how to carry out paper chromatography to find out whether a sample of a drug contains impurities.`, marks: 6, diagram: true, markScheme: `Level 3 (5–6 marks): a clear, logically ordered method that would give valid results, including how the chromatogram shows purity.\nLevel 2 (3–4 marks): a workable method with some key steps.\nLevel 1 (1–2 marks): simple steps with little detail.\nIndicative content:\n• Draw a pencil start line about 1–2 cm from the bottom of the paper (1)\n• Put a small concentrated spot of the drug, and a spot of the pure drug as reference, on the line (1)\n• Stand the paper in a suitable solvent with the solvent below the start line; cover with a lid (1)\n• Remove the paper before the solvent reaches the top and mark the solvent front; dry the paper (1)\n• Use a locating agent if the spots are colourless (1)\n• A pure drug gives one spot matching the reference; extra spots show impurities (1)` },
      { q: `Describe how to obtain pure, dry crystals of copper sulfate from copper sulfate solution.`, marks: 4, markScheme: `• Heat the solution in an evaporating basin to evaporate some of the water (1)\n• Stop heating when crystals start to form / at the crystallisation point (1)\n• Leave the solution to cool so that crystals form (1)\n• Filter off the crystals and dry them between filter papers / in a warm oven (1)` },
      { q: `Describe how simple distillation is used to obtain pure water from salt solution. Draw a labelled diagram of the apparatus.`, marks: 5, diagram: true, markScheme: `• Heat the salt solution in a flask so the water boils (1)\n• The water vapour passes into a condenser (1)\n• Cold water flows through the condenser jacket (in at the bottom, out at the top), cooling the vapour so it condenses (1)\n• Pure water (distillate) is collected in a beaker; salt is left in the flask (1)\n• Diagram: flask, thermometer bulb level with the side arm, condenser and collecting vessel correctly labelled (1)` },
      { q: `Explain why fractional distillation, rather than simple distillation, is used to separate ethanol (boiling point 78 °C) from water (boiling point 100 °C).`, marks: 3, markScheme: `• Ethanol and water have boiling points that are close together, so both evaporate and simple distillation would not separate them well (1)\n• A fractionating column gives a temperature gradient and many condensing/evaporating stages (1)\n• Ethanol, with the lower boiling point, reaches the top first and is collected when the thermometer reads about 78 °C (1)` },
      { q: `Suggest how you would separate each mixture: (a) sand from salt water, (b) the dyes in a sample of ink, (c) petrol from diesel. Give a reason for each.`, marks: 3, markScheme: `• (a) Filtration: sand is insoluble so it stays on the filter paper (1)\n• (b) Chromatography: the dyes are soluble and have different attractions to the phases (1)\n• (c) Fractional distillation: they are miscible liquids with different boiling points (1)` },
      { q: `Explain the purpose of taking representative samples when analysing a large batch of material such as soil from a field.`, marks: 2, markScheme: `• A small sample must have the same composition as the whole batch so that the results apply to all of it (1)\n• Samples are taken from several different places/times to identify any variation in the bulk material (1)` },
      { q: `Describe how to carry out a flame test on a solid compound.`, marks: 3, markScheme: `• Clean a nichrome wire loop by dipping it in hydrochloric acid and heating it in a Bunsen flame until it gives no colour (1)\n• Dip the loop into the solid sample (1)\n• Hold it in the edge of a blue (roaring) Bunsen flame and observe the colour (1)` },
      { q: `Give the flame test colours for lithium, sodium, potassium, calcium and copper ions.`, marks: 5, markScheme: `• Lithium: crimson (red) (1)\n• Sodium: yellow (orange-yellow) (1)\n• Potassium: lilac (1)\n• Calcium: orange-red (brick red) (1)\n• Copper: green (blue-green) (1)` },
      { q: `A few drops of dilute sodium hydroxide solution are added to separate solutions of copper(II) sulfate, iron(II) sulfate and iron(III) chloride. Give the colour of the precipitate formed in each case.`, marks: 3, markScheme: `• Copper(II): blue precipitate (1)\n• Iron(II): green precipitate (1)\n• Iron(III): orange-brown precipitate (1)` },
      { q: `Solutions of calcium nitrate and zinc nitrate both give a white precipitate with a few drops of sodium hydroxide solution. Explain how you could tell them apart.`, marks: 2, markScheme: `• Add excess sodium hydroxide solution (1)\n• The zinc hydroxide precipitate dissolves to give a colourless solution; the calcium hydroxide precipitate does not dissolve (1)` },
      { q: `Describe tests to show whether a solution contains chloride, bromide or iodide ions, giving the results.`, marks: 4, markScheme: `• Add dilute nitric acid, then silver nitrate solution (1)\n• Chloride: white precipitate (1)\n• Bromide: cream precipitate (1)\n• Iodide: yellow precipitate (1)` },
      { q: `Describe tests to identify carbonate ions and sulfate ions in a solid, giving the results.`, marks: 4, markScheme: `• Carbonate: add dilute acid; fizzing — the gas turns limewater milky (carbon dioxide) (1)\n• This shows carbonate is present (1)\n• Sulfate: dissolve in water, add dilute hydrochloric acid then barium chloride solution (1)\n• A white precipitate (barium sulfate) shows sulfate is present (1)` },
      { q: `In emission spectroscopy, reference lines are: lithium 610 nm and 671 nm; sodium 589 nm and 590 nm; potassium 766 nm and 770 nm; calcium 423 nm. A sample gave lines at 589, 590, 610 and 671 nm. Identify the elements in the sample and explain your answer.`, marks: 3, markScheme: `• Lithium (1)\n• Sodium (1)\n• Every line in each element's reference pattern appears in the sample; there are no lines at 766/770 nm or 423 nm, so potassium and calcium are absent (1)` },
      { q: `Give three advantages of instrumental methods of analysis such as emission spectroscopy over laboratory tests, and one disadvantage.`, marks: 4, markScheme: `• More sensitive: detect very small amounts (1)\n• More accurate (1)\n• Faster, and data is recorded automatically (1)\n• Disadvantage: the equipment is expensive and needs trained operators / is not widely available (1)` },
      { q: `Explain the difference between qualitative and quantitative analysis.`, marks: 2, markScheme: `• Qualitative analysis identifies which substances are present (1)\n• Quantitative analysis measures how much of each substance is present (1)` },
      { q: `When magnesium ribbon is heated in an open crucible its mass increases. When calcium carbonate is heated its mass decreases. Explain both observations using the particle model.`, marks: 4, markScheme: `• Mass is conserved: atoms are not created or destroyed, only rearranged (1)\n• Magnesium atoms combine with oxygen atoms from the air, so the product has a greater mass (1)\n• Calcium carbonate decomposes, forming calcium oxide and carbon dioxide (1)\n• The carbon dioxide gas escapes into the air from the open container, so the mass decreases (1)` },
      { q: `Calculate the relative formula masses of (a) CaCO₃ and (b) Ca(OH)₂. Relative atomic masses: Ca = 40, C = 12, O = 16, H = 1.`, marks: 3, markScheme: `• (a) 40 + 12 + (3 × 16) = 100 (1)\n• (b) 40 + 2 × (16 + 1) (1)\n• = 74 (1)` },
      { q: `Heating 100 g of calcium carbonate produces 56 g of calcium oxide: CaCO₃ → CaO + CO₂. Calculate the theoretical mass of calcium oxide that could be made from 50 g of calcium carbonate. In an experiment 22.4 g was obtained; calculate the percentage yield.`, marks: 4, markScheme: `• Theoretical mass = 50 × 56/100 (1)\n• = 28 g (1)\n• Percentage yield = (22.4 ÷ 28) × 100 (1)\n• = 80% (1)` },
      { q: `Suggest three reasons why the actual yield of a salt made in the laboratory is usually less than the theoretical yield.`, marks: 3, markScheme: `• Some product is lost during transfers, filtering or evaporation (1)\n• The reactants may be impure, or the reaction may be reversible/incomplete (1)\n• Side reactions may produce other, unwanted products (1)` },
      { q: `State the value of the Avogadro constant and calculate the number of molecules in 0.50 mol of water. [HT]`, marks: 2, markScheme: `• 6.02 × 10²³ (particles per mole) (1)\n• 0.50 × 6.02 × 10²³ = 3.01 × 10²³ molecules (1)` },
      { q: `Calculate the number of moles in 8.0 g of sodium hydroxide, NaOH, and the mass of 0.25 mol of carbon dioxide, CO₂. Relative atomic masses: Na = 23, O = 16, H = 1, C = 12. [HT]`, marks: 4, markScheme: `• Mr NaOH = 40 (1)\n• Moles = 8.0 ÷ 40 = 0.20 mol (1)\n• Mr CO₂ = 44 (1)\n• Mass = 0.25 × 44 = 11 g (1)` },
      { q: `4.8 g of magnesium reacts completely with 3.2 g of oxygen, O₂, to make 8.0 g of magnesium oxide, MgO. Use these masses to deduce the balanced equation. Relative atomic masses: Mg = 24, O = 16. [HT]`, marks: 4, markScheme: `• Moles Mg = 4.8 ÷ 24 = 0.20 mol (1)\n• Moles O₂ = 3.2 ÷ 32 = 0.10 mol (1)\n• Moles MgO = 8.0 ÷ 40 = 0.20 mol; ratio 2 : 1 : 2 (1)\n• 2Mg + O₂ → 2MgO (1)` },
      { q: `2.4 g of magnesium is added to a solution containing 0.10 mol of hydrochloric acid: Mg + 2HCl → MgCl₂ + H₂. Show which reactant is limiting and explain what this means. Relative atomic mass: Mg = 24. [HT]`, marks: 3, markScheme: `• Moles Mg = 2.4 ÷ 24 = 0.10 mol, which needs 0.20 mol HCl (1)\n• Only 0.10 mol HCl is present, so hydrochloric acid is the limiting reactant (1)\n• The limiting reactant is used up first and determines the amount of product made; some magnesium is left over (1)` },
      { q: `Calculate the mass of calcium oxide made when 25 g of calcium carbonate is heated: CaCO₃ → CaO + CO₂. Relative formula masses: CaCO₃ = 100, CaO = 56. [HT]`, marks: 3, markScheme: `• Moles CaCO₃ = 25 ÷ 100 = 0.25 mol (1)\n• Moles CaO = 0.25 mol (1 : 1 ratio) (1)\n• Mass = 0.25 × 56 = 14 g (1)` },
      { q: `Calculate the volume of hydrogen, at room temperature and pressure, made when 2.4 g of magnesium reacts with excess acid: Mg + 2HCl → MgCl₂ + H₂. Mg = 24; one mole of gas occupies 24 dm³ at RTP. [HT]`, marks: 3, markScheme: `• Moles Mg = 2.4 ÷ 24 = 0.10 mol (1)\n• Moles H₂ = 0.10 mol (1)\n• Volume = 0.10 × 24 = 2.4 dm³ (1)` },
      { q: `Nitrogen reacts with hydrogen: N₂(g) + 3H₂(g) → 2NH₃(g). Calculate the volume of nitrogen needed to react with 60 cm³ of hydrogen, and the volume of ammonia formed, all at the same temperature and pressure. [HT]`, marks: 2, markScheme: `• Nitrogen: 60 ÷ 3 = 20 cm³ (1)\n• Ammonia: 20 × 2 = 40 cm³ (1)` },
      { q: `5.0 g of copper sulfate is dissolved in water to make 250 cm³ of solution. Calculate the concentration in g/dm³. [HT]`, marks: 2, markScheme: `• Volume = 250 ÷ 1000 = 0.250 dm³ (1)\n• Concentration = 5.0 ÷ 0.250 = 20 g/dm³ (1)` },
      { q: `4.0 g of sodium hydroxide (Mr = 40) is dissolved to make 500 cm³ of solution. Calculate the concentration in mol/dm³. [HT]`, marks: 3, markScheme: `• Moles = 4.0 ÷ 40 = 0.10 mol (1)\n• Volume = 0.500 dm³ (1)\n• Concentration = 0.10 ÷ 0.500 = 0.20 mol/dm³ (1)` },
      { q: `Describe how to carry out a titration to find the volume of hydrochloric acid needed to neutralise 25.0 cm³ of sodium hydroxide solution.`, marks: 6, markScheme: `Level 3 (5–6 marks): a detailed, logically ordered method that would give precise, accurate and repeatable results.\nLevel 2 (3–4 marks): a workable method with some detail of equipment and endpoint.\nLevel 1 (1–2 marks): simple statements about adding acid to alkali.\nIndicative content:\n• Use a pipette (with filler) to measure 25.0 cm³ of sodium hydroxide into a conical flask (1)\n• Add a few drops of indicator, e.g. phenolphthalein or methyl orange (1)\n• Fill a burette with hydrochloric acid and record the starting reading at eye level from the bottom of the meniscus (1)\n• Add the acid while swirling the flask, adding dropwise near the endpoint, until the indicator just changes colour; record the final reading (1)\n• Do a rough titration first, then repeat accurately (1)\n• Repeat until concordant titres (within 0.10 cm³) are obtained and calculate the mean of these (1)` },
      { q: `Titres recorded in a titration were: rough 24.90 cm³, then 24.20 cm³, 24.25 cm³, 24.60 cm³ and 24.20 cm³. Calculate the mean titre and explain which results you used.`, marks: 3, markScheme: `• Ignore the rough titre and the anomalous 24.60 cm³ (1)\n• Use the concordant results 24.20, 24.25 and 24.20 cm³ (within 0.10 cm³ of each other) (1)\n• Mean = 72.65 ÷ 3 = 24.22 cm³ (1)` },
      { q: `Write the ionic equation for all neutralisation reactions between acids and alkalis in solution, and name the ions present in solutions of acids and of alkalis.`, marks: 3, markScheme: `• Acids contain hydrogen ions, H⁺(aq) (1)\n• Alkalis contain hydroxide ions, OH⁻(aq) (1)\n• H⁺(aq) + OH⁻(aq) → H₂O(l) (1)` },
      { q: `25.0 cm³ of 0.100 mol/dm³ sodium hydroxide was neutralised by 20.0 cm³ of hydrochloric acid: NaOH + HCl → NaCl + H₂O. Calculate the concentration of the acid. [HT]`, marks: 3, markScheme: `• Moles NaOH = 0.100 × 25.0/1000 = 0.00250 mol (1)\n• Moles HCl = 0.00250 mol (1 : 1) (1)\n• Concentration HCl = 0.00250 ÷ 0.0200 = 0.125 mol/dm³ (1)` },
      { q: `25.0 cm³ of 0.100 mol/dm³ sodium hydroxide was neutralised by 12.50 cm³ of sulfuric acid: 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. Calculate the concentration of the sulfuric acid in mol/dm³. [HT]`, marks: 4, markScheme: `• Moles NaOH = 0.100 × 0.0250 = 0.00250 mol (1)\n• Moles H₂SO₄ = 0.00250 ÷ 2 = 0.00125 mol (1)\n• Volume of acid = 0.01250 dm³ (1)\n• Concentration = 0.00125 ÷ 0.01250 = 0.100 mol/dm³ (1)` },
    ],
  },


  /* ═══════════════════════════════════════ C6 — Making Useful Chemicals */
  'C6': {
    name: 'Making Useful Chemicals',
    questions: [
      { q: `Write word equations for the reactions of (a) zinc with hydrochloric acid and (b) copper carbonate with sulfuric acid.`, marks: 4, markScheme: `• (a) zinc + hydrochloric acid → zinc chloride (1)\n• + hydrogen (1)\n• (b) copper carbonate + sulfuric acid → copper sulfate (1)\n• + water + carbon dioxide (1)` },
      { q: `Write a balanced symbol equation for the reaction of calcium carbonate with hydrochloric acid.`, marks: 2, markScheme: `• Correct formulae: CaCO₃ + HCl → CaCl₂ + H₂O + CO₂ (1)\n• Balanced: CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ (1)` },
      { q: `Use the formulae of the ions to write the formulae of (a) magnesium sulfate, (b) aluminium chloride and (c) ammonium nitrate. Ions: Mg²⁺, SO₄²⁻, Al³⁺, Cl⁻, NH₄⁺, NO₃⁻.`, marks: 3, markScheme: `• (a) MgSO₄ (1)\n• (b) AlCl₃ (1)\n• (c) NH₄NO₃ (1)` },
      { q: `Describe how to make a pure, dry sample of copper sulfate crystals from copper oxide and dilute sulfuric acid.`, marks: 6, markScheme: `Level 3 (5–6 marks): a clear, logically ordered method that would produce pure, dry crystals, with reasons for key steps.\nLevel 2 (3–4 marks): a method with the main steps but some omissions.\nLevel 1 (1–2 marks): simple statements about reacting the two substances.\nIndicative content:\n• Warm the dilute sulfuric acid in a beaker (1)\n• Add copper oxide a little at a time, stirring, until no more dissolves (excess), so that all the acid is used up (1)\n• Filter to remove the excess copper oxide (1)\n• Heat the filtrate in an evaporating basin to evaporate some water until crystals start to form (1)\n• Leave to cool and crystallise (1)\n• Filter off the crystals and dry them between filter papers or in a warm oven (1)` },
      { q: `Explain why excess solid is added when making a salt from an acid and an insoluble base or carbonate.`, marks: 2, markScheme: `• To make sure all of the acid reacts / is neutralised (1)\n• The unreacted solid can then be removed easily by filtration, leaving only the salt solution (1)` },
      { q: `Give the pH ranges for acidic, neutral and alkaline solutions, and name two ways of measuring pH.`, marks: 3, markScheme: `• Acidic: pH below 7; neutral: pH 7; alkaline: pH above 7 (1)\n• Universal indicator (paper or solution) compared with a colour chart (1)\n• pH meter / pH probe (1)` },
      { q: `Explain the difference between a strong acid and a weak acid, giving an example of each. [HT]`, marks: 3, markScheme: `• A strong acid is completely ionised in water (1)\n• A weak acid is only partially ionised in water (1)\n• Strong: hydrochloric, nitric or sulfuric acid; weak: ethanoic, citric or carbonic acid (1)` },
      { q: `Explain the difference between a dilute acid and a weak acid. [HT]`, marks: 2, markScheme: `• Dilute refers to concentration: a small amount of acid per unit volume (1)\n• Weak refers to the degree of ionisation: only some acid molecules ionise (1)` },
      { q: `Hydrochloric acid and ethanoic acid of the same concentration (1.0 mol/dm³) are each reacted with identical pieces of magnesium. Explain the differences you would observe. [HT]`, marks: 3, markScheme: `• Hydrochloric acid reacts faster / fizzes more vigorously (1)\n• Hydrochloric acid is strong and completely ionised, so it has a higher concentration of H⁺ ions (1)\n• Ethanoic acid is weak and only partially ionised, so fewer H⁺ ions are available and the reaction is slower; it also has a higher pH (1)` },
      { q: `Solution A has pH 2 and solution B has pH 5. Calculate how many times greater the hydrogen ion concentration is in A than in B. [HT]`, marks: 2, markScheme: `• pH difference = 3; each unit is a factor of 10 (1)\n• 10³ = 1000 times greater (1)` },
      { q: `Describe how the pH of a solution is related to the concentration of hydrogen ions, and state the pH of a neutral solution. [HT]`, marks: 3, markScheme: `• The higher the H⁺ ion concentration, the lower the pH (1)\n• When the H⁺ concentration increases by a factor of 10, the pH decreases by 1 (1)\n• A neutral solution has pH 7 (equal concentrations of H⁺ and OH⁻) (1)` },
      { q: `Describe the effect on the rate of reaction of increasing (a) temperature, (b) concentration of a solution, (c) pressure of a gas and (d) surface area of a solid.`, marks: 4, markScheme: `• (a) Increases rate (1)\n• (b) Increases rate (1)\n• (c) Increases rate (for reactions involving gases) (1)\n• (d) Increases rate (1)` },
      { q: `Explain, using collision theory, why increasing the temperature increases the rate of a reaction.`, marks: 4, markScheme: `• Particles move faster / have more kinetic energy (1)\n• So they collide more frequently (1)\n• A greater proportion of collisions have energy equal to or greater than the activation energy (1)\n• So there are more successful collisions per second; the energy effect is the more significant (1)` },
      { q: `Explain, using collision theory, why increasing the concentration of an acid increases the rate of its reaction with marble chips.`, marks: 3, markScheme: `• There are more acid particles in the same volume (1)\n• So collisions between acid particles and the marble surface are more frequent (1)\n• So there are more successful collisions per second (1)` },
      { q: `A 1 cm marble cube is crushed into eight 0.5 cm cubes. Explain why the crushed marble reacts faster with acid, referring to surface area to volume ratio.`, marks: 3, markScheme: `• The smaller pieces have a larger surface area to volume ratio (the total surface area doubles from 6 cm² to 12 cm²) (1)\n• More particles are exposed to the acid (1)\n• So there are more frequent collisions and a faster rate (1)` },
      { q: `State what a catalyst is and explain how it increases the rate of a reaction.`, marks: 3, markScheme: `• A substance that increases the rate of reaction but is not used up / is unchanged at the end (1)\n• It provides an alternative reaction pathway (1)\n• with a lower activation energy, so more collisions are successful (1)` },
      { q: `Draw a reaction profile for an exothermic reaction with and without a catalyst. Label the activation energies.`, marks: 3, diagram: true, markScheme: `• Products lower than reactants (1)\n• Two curves, the catalysed one with a lower peak (1)\n• Activation energy labelled for each, from reactants to peak (1)` },
      { q: `When manganese(IV) oxide is added to hydrogen peroxide, oxygen is released rapidly. After the reaction, the same mass of manganese(IV) oxide is recovered. Identify the catalyst and explain how the evidence shows this.`, marks: 2, markScheme: `• Manganese(IV) oxide (1)\n• It speeds up the decomposition but is not used up / its mass is unchanged (1)` },
      { q: `Describe two methods of following the rate of the reaction between magnesium and hydrochloric acid.`, marks: 4, markScheme: `• Collect the hydrogen in a gas syringe (or by displacement of water in an upturned measuring cylinder) (1)\n• Record the volume of gas at regular time intervals (1)\n• Alternatively, carry out the reaction in a flask on a balance (1)\n• and record the decrease in mass at regular intervals as hydrogen escapes (1)` },
      { q: `Sodium thiosulfate reacts with hydrochloric acid to form a yellow precipitate of sulfur. Describe how the rate of this reaction could be measured. [HT]`, marks: 3, markScheme: `• Place the flask on a cross drawn on paper (1)\n• Time how long it takes for the cross to disappear as the precipitate forms (or use a colorimeter/light sensor to measure the change in light transmitted) (1)\n• Rate is proportional to 1/time; shorter time = faster rate (1)` },
      { q: `Explain how the rate of a reaction that produces a colour change can be followed using a colorimeter. [HT]`, marks: 2, markScheme: `• The colorimeter measures how much light passes through (or is absorbed by) the solution (1)\n• Readings are taken at time intervals; the faster the change in absorbance, the faster the rate (1)` },
      { q: `In a reaction 48 cm³ of carbon dioxide was produced in the first 60 s. Calculate the mean rate of reaction in cm³/s.`, marks: 2, markScheme: `• Mean rate = 48 ÷ 60 (1)\n• = 0.80 cm³/s (1)` },
      { q: `Marble chips reacting with acid lost 2.20 g of mass in 50 s. Calculate the mean rate of reaction in g/s.`, marks: 2, markScheme: `• 2.20 ÷ 50 (1)\n• = 0.044 g/s (1)` },
      { q: `Volume of hydrogen (cm³) at times 0, 20, 40, 60, 80, 100 s was 0, 30, 50, 62, 68, 68. Plot a graph of these results and describe how the rate changes during the reaction.`, marks: 5, diagram: true, markScheme: `• Axes labelled with units: time (s) on x-axis, volume (cm³) on y-axis, sensible scales (1)\n• All points plotted correctly (1)\n• Smooth curve of best fit drawn (1)\n• Rate is fastest at the start (steepest gradient) and decreases (1)\n• Reaction stops at about 80 s (flat line) because a reactant is used up (1)` },
      { q: `A tangent drawn to a volume–time curve at 20 s passes through the points (0 s, 10 cm³) and (40 s, 50 cm³). Calculate the rate of reaction at 20 s.`, marks: 2, markScheme: `• Gradient = (50 − 10) ÷ (40 − 0) (1)\n• = 1.0 cm³/s (1)` },
      { q: `Doubling the concentration of acid halved the time for a reaction to finish. Describe the relationship between concentration and rate shown by this result.`, marks: 2, markScheme: `• Rate is proportional to 1/time, so the rate doubled (1)\n• Rate is directly proportional to concentration (1)` },
      { q: `A student measured the time taken for a reaction at different temperatures: 20 °C, 80 s; 30 °C, 40 s; 40 °C, 20 s; 50 °C, 10 s. Describe the pattern and use it to predict the time at 60 °C. [HT]`, marks: 3, markScheme: `• As temperature increases the time decreases / rate increases (1)\n• Each 10 °C rise halves the time / doubles the rate (1)\n• Predicted time at 60 °C = 5 s (1)` },
      { q: `Describe how enzymes act as catalysts and explain one advantage and one disadvantage of using enzymes in industrial processes.`, marks: 4, markScheme: `• Enzymes are proteins that catalyse reactions in living organisms (1)\n• They work best within a narrow range of temperature and pH (1)\n• Advantage: they work at lower temperatures, reducing energy demand and cost (1)\n• Disadvantage: they are denatured at high temperatures/wrong pH, which limits the conditions that can be used (1)` },
      { q: `Explain what the symbol ⇌ means and why a reversible reaction in a closed system never gives a 100% yield.`, marks: 3, markScheme: `• ⇌ shows a reversible reaction: the products can react to re-form the reactants (1)\n• As products form, some of them react to form reactants again (1)\n• So the reactants are never completely converted to products (1)` },
      { q: `Explain what is meant by dynamic equilibrium.`, marks: 2, markScheme: `• The forward and reverse reactions continue to happen (1)\n• at the same rate, so the amounts of reactants and products stay constant (1)` },
      { q: `For the reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g) (forward reaction exothermic), predict the effect on the yield of ammonia of (a) increasing the pressure and (b) increasing the temperature. Explain each answer. [HT]`, marks: 4, markScheme: `• (a) Yield increases (1)\n• There are fewer molecules of gas on the right (2 vs 4), so the equilibrium shifts to the right to reduce the pressure (1)\n• (b) Yield decreases (1)\n• The forward reaction is exothermic, so the equilibrium shifts in the endothermic (reverse) direction (1)` },
      { q: `Explain why adding a catalyst to a reversible reaction does not change the yield at equilibrium. [HT]`, marks: 2, markScheme: `• A catalyst increases the rates of the forward and reverse reactions equally (1)\n• So equilibrium is reached faster but its position (yield) is unchanged (1)` },
      { q: `Explain the disadvantages of using very high pressures and very high temperatures in industrial processes. [HT]`, marks: 3, markScheme: `• Expensive to maintain because of high energy costs (1)\n• Equipment must be very strong/thick-walled, which is costly to build (1)\n• Greater safety risks, as equipment may fail/explode under extreme conditions (1)` },
      { q: `Explain why nitrogen, phosphorus and potassium compounds are added to farmland as fertilisers.`, marks: 3, markScheme: `• Plants need nitrogen, phosphorus and potassium as essential elements for growth (1)\n• These elements are removed from the soil when crops use them and are then harvested (1)\n• Fertilisers replace them so that crop yields stay high (1)` },
      { q: `Explain why synthetic fertilisers are needed to feed the world, and describe the environmental problem caused when fertilisers are overused.`, marks: 4, markScheme: `• Natural fertilisers (manure) are not available in large enough quantities, are hard to transport and have variable composition (1)\n• Synthetic fertilisers allow high crop yields to meet world food demand (1)\n• Excess fertiliser is washed into rivers and lakes, causing excessive growth of algae/weeds (eutrophication) (1)\n• When these die, bacteria decompose them and use up the oxygen, so fish and other organisms die (1)` },
      { q: `Discuss how the conditions used in the Haber process (iron catalyst, about 450 °C and 200 atmospheres) are chosen, including the raw materials and the recycling of unreacted gases. N₂(g) + 3H₂(g) ⇌ 2NH₃(g); the forward reaction is exothermic. [HT]`, marks: 6, markScheme: `Level 3 (5–6 marks): a detailed discussion of raw materials, all three conditions as compromises between rate, yield and cost, and recycling.\nLevel 2 (3–4 marks): explains the choice of some conditions with some reference to rate or yield.\nLevel 1 (1–2 marks): simple statements about the conditions or raw materials.\nIndicative content:\n• Nitrogen comes from the air; hydrogen comes from natural gas (methane) reacting with steam (1)\n• A low temperature would give a higher yield (exothermic), but the rate would be too slow, so 450 °C is a compromise between rate and yield (1)\n• A high pressure increases yield (fewer gas molecules on the right) and rate (1)\n• But very high pressures are expensive and dangerous, so 200 atmospheres is a compromise (1)\n• The iron catalyst increases the rate without changing the yield, reducing energy costs (1)\n• The ammonia is cooled and liquefied to separate it; unreacted nitrogen and hydrogen are recycled so they are not wasted (1)` },
      { q: `Explain why the Haber process rarely reaches equilibrium in practice and why this is not a problem. [HT]`, marks: 2, markScheme: `• The gases pass through the reactor quickly, so there is not time to reach equilibrium / only about 15% converts per pass (1)\n• Ammonia is removed and unreacted gases are recycled, so overall almost all the reactants are converted (1)` },
      { q: `Define atom economy and calculate the atom economy for making calcium oxide from calcium carbonate: CaCO₃ → CaO + CO₂. Relative formula masses: CaCO₃ = 100, CaO = 56.`, marks: 3, markScheme: `• Atom economy = (mass of atoms in desired product ÷ total mass of atoms in reactants) × 100 (1)\n• = (56 ÷ 100) × 100 (1)\n• = 56% (1)` },
      { q: `Ethanol can be made by fermentation, C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂, or by hydration of ethene, C₂H₄ + H₂O → C₂H₅OH. Relative formula masses: C₆H₁₂O₆ = 180, C₂H₅OH = 46. Calculate the atom economy of each and explain which route is more sustainable in terms of atom economy, and why fermentation may still be chosen. [HT]`, marks: 5, markScheme: `• Fermentation: (2 × 46) ÷ 180 × 100 (1)\n• = 51% (1)\n• Hydration: 100% (only one product) (1)\n• Hydration has the higher atom economy, so less waste is produced (1)\n• Fermentation uses renewable raw materials (sugar from plants), whereas ethene comes from finite crude oil; the CO₂ by-product may also be used (1)` },
      { q: `Ammonium sulfate fertiliser can be made in the laboratory or industrially. Compare the two methods of production.`, marks: 6, markScheme: `Level 3 (5–6 marks): a detailed comparison of laboratory and industrial production covering raw materials, scale, process type and sources.\nLevel 2 (3–4 marks): some valid comparisons.\nLevel 1 (1–2 marks): a simple description of one method.\nIndicative content:\n• Laboratory: ammonia solution is titrated/neutralised with dilute sulfuric acid, then crystallised (1)\n• Laboratory: small-scale batch process using purchased pure chemicals (1)\n• Industry: large-scale continuous process making ammonia and sulfuric acid from raw materials (air, natural gas, water, sulfur) (1)\n• Industry: integrated processes summarised in a flow chart showing raw materials, stages, products, by-products and waste (1)\n• Industry: ammonium sulfate is also made as a by-product of other processes, so demand is met from more than one source (1)\n• Industrial plants are highly automated, recycle reactants and use energy from exothermic reactions efficiently (1)` },
    ],
  },


};

if (typeof window !== 'undefined') window.CHEMISTRY_OCR_B_GCSE_PRACTICE = CHEMISTRY_OCR_B_GCSE_PRACTICE;
if (typeof module !== 'undefined' && module.exports) module.exports = CHEMISTRY_OCR_B_GCSE_PRACTICE;
